package com.example.rokidgeminisecretary;
import android.content.*;import android.util.AtomicFile;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;
/** One atomic encrypted inbox, including receipts/tombstones, for retry-safe log imports. */
final class ImportedAnswers {
 static JSONObject checked(JSONObject raw)throws Exception{String id=raw.getString("id"),kind=raw.getString("kind"),message=raw.getString("message"),request=raw.optString("requestId");long at=raw.getLong("time");if(!id.matches("[a-f0-9]{64}")||!kind.matches("ユーザー|ユーザー音声|Gemini|直接回答")||message.trim().isEmpty()||message.length()>64000||at<=0||!request.isEmpty()&&!TrackedWebRequest.validId(request))throw new IOException("回答ログの形式を確認してください");return new JSONObject().put("id",id).put("kind",kind).put("message",message).put("requestId",request).put("time",at).put("legacy",raw.optBoolean("legacy"));}
 static String signature(JSONObject row)throws Exception{JSONObject normalized=checked(row);if(TrackedWebRequest.validId(normalized.optString("requestId")))normalized.remove("time");return ReviewStore.hash(normalized);}
 static JSONObject store(Context c)throws Exception{try{if(ConversationWorkspace.file(c,"answer-imports").getBaseFile().length()>32*1024*1024)throw new IOException("取り込み済み回答の容量を確認してください");return ConversationWorkspace.read(c,"answer-imports");}catch(FileNotFoundException absent){return new JSONObject().put("items",new JSONArray());}}
 static synchronized JSONObject accept(Context c,JSONObject raw)throws Exception{JSONObject row=checked(raw),store=store(c);JSONArray rows=store.getJSONArray("items");for(int i=0;i<rows.length();i++){JSONObject prior=rows.getJSONObject(i);if(row.getString("id").equals(prior.getString("id"))){String old=prior.optBoolean("hidden")?prior.optString("contentHash"):signature(prior);if(!old.equals(signature(row)))throw new IOException("同じ転送IDの内容が異なります");return new JSONObject().put("ok",true).put("id",row.getString("id")).put("duplicate",true);}}if(rows.length()>=2000)throw new IOException("取り込み済み回答が上限です。メガネの転送待ちは保持します");rows.put(row);if(store.toString().getBytes(StandardCharsets.UTF_8).length>16*1024*1024)throw new IOException("取り込み済み回答の容量が上限です");ConversationWorkspace.write(c,"answer-imports",store);return new JSONObject().put("ok",true).put("id",row.getString("id"));}
 static synchronized java.util.ArrayList<JSONObject> merge(Context c,java.util.ArrayList<JSONObject> base)throws Exception{java.util.ArrayList<JSONObject> result=new java.util.ArrayList<>(base);JSONArray rows=store(c).getJSONArray("items");java.util.HashSet<String> oldBodies=new java.util.HashSet<>();for(JSONObject b:base)oldBodies.add(b.optString("kind")+":"+b.optString("message"));for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(row.optBoolean("hidden")||row.optBoolean("legacy")&&oldBodies.contains(row.optString("kind")+":"+row.optString("message")))continue;JSONObject view=new JSONObject(row.toString());view.put("syncId",view.remove("id"));result.add(view);}result.sort((a,b)->Long.compare(a.optLong("time"),b.optLong("time")));return result;}
 static synchronized int hide(Context c,java.util.Set<String> keys,java.util.Set<String> bodies)throws Exception{JSONObject store=store(c);JSONArray rows=store.getJSONArray("items");int count=0;for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(!row.optBoolean("hidden")&&(keys.contains(row.optString("requestId"))||bodies.contains(row.optLong("time")+":"+row.optString("kind")+":"+row.optString("message")))){row.put("contentHash",signature(row)).put("hidden",true);row.remove("message");count++;}}if(count>0)ConversationWorkspace.write(c,"answer-imports",store);return count;}
 static synchronized boolean received(Context c,String key)throws Exception{if(!TrackedWebRequest.validId(key))return false;JSONArray rows=store(c).getJSONArray("items");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(!row.optBoolean("hidden")&&key.equals(row.optString("requestId"))&&!row.optString("kind").startsWith("ユーザー"))return true;}return false;}
 private ImportedAnswers(){}
}
